SET search_path TO lms, extensions;

-- Permit activity for the same module/learner assignment authorized by teaching actions.
BEGIN;
CREATE OR REPLACE FUNCTION lms.log_activity_for_user(
  target_user_id UUID,
  activity activity_event,
  target_entity_type TEXT DEFAULT NULL,
  target_entity_id UUID DEFAULT NULL,
  activity_metadata JSONB DEFAULT '{}'::JSONB
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
DECLARE
  inserted_id UUID;
  teaching_module_id UUID;
BEGIN
  IF NOT lms.is_active_app_user(auth.uid()) THEN
    RAISE EXCEPTION 'inactive or unauthenticated user cannot log activity';
  END IF;

  IF target_entity_type = 'modules' THEN
    teaching_module_id := target_entity_id;
  ELSIF target_entity_type = 'module_versions' THEN
    SELECT module_id INTO teaching_module_id FROM lms.module_versions WHERE id = target_entity_id;
  END IF;

  IF target_user_id <> auth.uid()
     AND NOT lms.is_super_admin()
     AND NOT lms.is_assigned_teacher(target_user_id)
     AND NOT (
       teaching_module_id IS NOT NULL
       AND lms.can_teach_module(teaching_module_id)
       AND EXISTS (SELECT 1 FROM lms.learner_progress
         WHERE learner_id = target_user_id AND module_id = teaching_module_id
           AND teacher_id = auth.uid())
     ) THEN
    RAISE EXCEPTION 'not authorized to log activity for target user';
  END IF;

  INSERT INTO lms.activity_logs (
    user_id,
    event,
    entity_type,
    entity_id,
    metadata
  )
  VALUES (
    target_user_id,
    activity,
    target_entity_type,
    target_entity_id,
    COALESCE(activity_metadata, '{}'::JSONB)
  )
  RETURNING id INTO inserted_id;

  RETURN inserted_id;
END;
$$;
COMMIT;
